def pages():
    P=[]
    # ---------- 1: intro ----------
    P.append(page(1,K,"הפארקים הלאומיים: מעבדות הטבע של המערב","US National Parks",
    hero=sf("usparks","<b>מפת רליף של מערב ארצות הברית.</b> הפארקים הנסקרים בחלק זה מסומנים בעיגולים ירוקים. הרקע: מערך הרליף ETOPO1 של NOAA (רזולוציה של כ-7 ק״מ לפיקסל). שדה הרליף מדגיש את מערכות ההרים המקבילות לחוף ואת הקשר בין הרכסים לאגנים הצחיחים שמזרחם.","w3")+sf("hb_area","<b>שטח הפארקים</b> (קמ״ר, לפי NPS; דנאלי, 24,585 קמ״ר, מחוץ לסקלה).","w2"),
    cols=f'''
{box("","כרטיס הזיהוי של שמונת הפארקים המרכזיים",table([["ילוסטון","1872","3,462 (אגל פיק)"],["יוסמיטי","1890","3,999 (ליל)"],["ריינייר","1899","4,392 (ריינייר)"],["גלייסר","1910","3,190 (קליבלנד)"],["רוקי מאונטן","1915","4,346 (לונגס)"],["גרנד טיטון","1929","4,199 (גרנד טיטון)"],["אולימפיק","1938","2,432 (אולימפוס)"],["צפון הקסקייד","1968","~2,800 (גוּד)"]],["פארק","הוקם","הנקודה הגבוהה (מ׳)"]),"")}
<p>ב-1 במרץ 1872 חתם הנשיא יוליסס גרנט על חוק שהקים את <b>ילוסטון</b>, הפארק הלאומי הראשון בעולם. ב-1916 הוקם שירות הפארקים הלאומיים (NPS), שמנהל כיום 63 פארקים לאומיים בתוך מערך של יותר מ-400 יחידות המשתרעות על כ-340 אלף קמ"ר. בשנת 2023 נרשמו כ-325 מיליון ביקורים בכלל יחידות השירות (נתוני NPS).</p>
<p>מדוע המערב מרוכז בנופים הדרמטיים ביותר? התשובה גאולוגית. מערב צפון אמריקה הוא אזור פעיל ב-200 המיליונים האחרונים: תת-שקיעה של לוחות האוקיינוס מתחת ליבשת בנתה את הסיירה נבדה ואת הקסקייד; תהליך לארמידי (~80 עד 40 מיליון שנה) הרים את הרוקי; ועל אלה נוספו נקודה חמה במעטפת (ילוסטון), התרחבות הקרום באגן וטווח (טיטון) ועידן הקרח, שפיסל מחדש כמעט כל פסגה גבוהה.</p>
<h2>איך קוראים פארק</h2>
<p>בכל פארק בחלק זה נפעל לפי שרשרת סיבתית אחת: <b>סלע ← תבליט ← אקלים ← מים ← אקולוגיה ← האדם</b>. סוג הסלע (גרניט, בזלת, גיר) קובע את צורת הנוף והקרקע; הגובה והכיוון קובעים את הטמפרטורה והמשקעים; המים (שלג, קרחון, נחל) מעצבים את הקרקע ומזינים אקוסיסטמות; האקוסיסטמות קובעות מי יכול לחיות שם; והאדם, בתיירות, בכיבוי שריפות ובשינוי האקלים, משנה בתורו את כל החוליות.</p>
{box("data","הערה על נתונים","<p>גבהי פסגות משתנים מעט בין מקורות ושיטות מדידה (USGS, NPS, ופרסומי טופוגרפיה); בספר מובאים הערכים המקובלים של USGS/NPS מעוגלים למטר, וערכים משוערים מסומנים ב-״~״ או ״כ-״.</p>")}
<h2>מה מחבר בין הפארקים?</h2>
<p>כל שמונת הפארקים יושבים על <b>קו שבר גאולוגי-אקולוגי אחד</b>: המעבר מאוקיינוס לח לפנים היבשת היבש. הרוחות המערביות מעבירות אדי מים מהפסיפי; כל רכס הרים שמעמיד את עצמו בדרכן מקבל משקעים בצידו הפונה לרוח ומעמיד "צל גשם" מאחוריו. התוצאה היא הניגוד בין יערות הגשם של אולימפיק לעמק הצחיח של סקווים, כמה עשרות קילומטרים משם , וגם הסיבה לכך שקרחונים נשמרים במערב דווקא בצפון הקר והלח.</p>
{box("compare","פארקים הרריים: שלוש משפחות","<table class='dt'><tr><th>משפחה</th><th>פארקים</th><th>מנוע ההיווצרות</th></tr><tr><td>געשיים</td><td>ילוסטון, ריינייר</td><td>נקודה חמה / קשת געשית</td></tr><tr><td>בלוקי העתק וגרניט</td><td>טיטון, יוסמיטי</td><td>העתק, בטוליט ועידן הקרח</td></tr><tr><td>רכסי קפל ודחיפה</td><td>גלייסר, רוקי מאונטן, צפון הקסקייד</td><td>התנגשות/לארמיד וקרחונים</td></tr></table>")}
''',toc="מבוא: מעבדות הטבע של המערב",toc_level=2))
    # ---------- 2: RMNP I ----------
    P.append(page(1,K,"רוקי מאונטן: גג הרוקי הקולורדאיים","Rocky Mountain National Park",
    hero=sf("rmnp","<b>חתך מערב←מזרח סכמטי בפארק רוקי מאונטן.</b> שלושת רצועות הצמחייה (מונטן, תת-אלפי, אלפי) משקפות את ירידת הטמפרטורה בכ-6°C לכל 1,000 מ׳ גובה. הגבהים: NPS/USGS; הגבולות בין הרצועות מקורבים.",""),
    cols=f'''
{idcard("תעודת זהות: רוקי מאונטן",[("הוקם","1915"),("שטח","1,076 קמ״ר"),("גבהים","2,396 עד 4,346 מ׳"),("פסגות מעל 3,658 מ׳","יותר מ-60"),("מיקום","קולורדו, רכס הפרונט")])}
<p>רוקי מאונטן הוא פארק של מדרגות גובה. תוך שעה נסיעה אפשר לעבור מעמק מיוער בגובה 2,400 מ׳ אל טונדרה אלפינית בגובה 3,700 מ׳, ובדרך לחוות שלוש אקוסיסטמות מובחנות. כשליש משטח הפארק נמצא מעל קו העצים, הנמוך מ-3,500 מ' בקירוב.</p>
<h2>גאולוגיה: ליבה עתיקה, הרמה צעירה</h2>
<p>ליבת הפארק בנויה מסלעי יסוד קדם-קמבריים: <b>גנייס וסכיסט</b> מטמורפיים בני כ-1.8 עד 1.7 מיליארד שנה, שנקרעו בידי חדירות <b>גרניט סילבר פלום</b> לפני כ-1.4 מיליארד שנה, הסלע שממנו עשוי לונגס פיק. בעשרות מיליוני השנים האחרונות, בעקבות התהליך הלארמידי (כ-70 עד 40 מיליון שנה), נדחף גוש היסוד כולו כלפי מעלה על פני שברים עמוקים.</p>
<p>בצפון-מערב הפארק, בהרי <b>נבר סאמר</b> (Never Summer), מתנשא רכס געשי צעיר יותר (כ-29 עד 25 מיליון שנה). פסגתו, ריכטהופן (3,934 מ׳), היא תזכורת לכך שבעבר היה כאן קו חם: חומר געשי הצטבר על גבי היסוד העתיק.</p>
<h2>עידן הקרח שפיסל את הפארק</h2>
<p>במהלך הפלייסטוקן הציפו קרחוני עמק את מרבית העמקים. שתי תקופות עיקריות מתועדות: <b>בול לייק</b> (כ-150 עד 130 אלף שנה) ו<b>פינדייל</b> (כ-30 עד 12 אלף שנה). המורנות הצדדיות הענקיות מקיפות היום את <b>מורן פארק</b>, וקרקסי הקרח, כמו אגם <b>צ׳אזם</b> מתחת לפניה המזרחיים של לונגס פיק (״הדיאמנט״, קיר של כ-300 מ׳), מדגימים את תהליך החציבה בצורתו הקלאסית. הקרחונים שנותרו, ביניהם טיילור, אנדרוז, טינדל ומילס, שטחם כולו קטן מקמ״ר ובנסיגה.</p>
{box("data","ציר זמן גאולוגי של הפארק",table([["1.8 עד 1.7 מיליארד שנה","גנייס וסכיסט (סלעי היסוד)"],["~1.4 מיליארד שנה","גרניט סילבר פלום (לונגס פיק)"],["~300 מיליון שנה","הרים עתיקים (״רוקי קדומים״) שנשחקו"],["70 עד 40 מיליון שנה","הרמה לארמידית של הרוקי"],["29 עד 25 מיליון שנה","געשיות נבר סאמר"],["30 עד 12 אלף שנה","קרחוני פינדייל"]]))}
<h2>מים: המקור של נהר קולורדו</h2>
<p>הפארק יושב על <b>פרשת המים היבשתית</b>: מים שנופלים ממערבה זורמים לאוקיינוס השקט, ומים מזרחה אל מפרץ מקסיקו. נהר קולורדו מתחיל בצפון-מערב הפארק (ליד מעבר לה פודר, ~3,100 מ׳), ואחרי כ-2,300 ק״מ הוא נבלע בחקלאות ובעריו ולעיתים כבר אינו מגיע לים. <b>אגם גרנד</b> (2,658 מ׳) הוא האגם הטבעי העמוק והנרחב ביותר בקולורדו, עם עומק של כ-80 מ׳. בפארק יותר מ-150 אגמים, רבים מהם אגמי קרקס קרחוניים.</p>
<p>האקלים מתאפיין בהבדלים חדים: בהרים הנמוכים נאספים כ-400 עד 500 מ״מ משקעים בשנה, ובגובה 3,500 מ׳ ומעלה יותר מ-1,000 מ״מ, בעיקר כשלג. טמפרטורה ממוצעת יורדת בכ-6°C לכל 1,000 מ׳ (שיעור הירידה האדיאבטית של אוויר לח, כ-5 עד 6.5°C).</p>
{box("nature","מדוע קו העצים משתנה בין רכסי הרים?","<p>קו העצים אינו קובע בגלל קור כשלעצמו אלא בגלל <b>איזון חום הקרקע בעונת הגידול</b>: עצים זקוקים לטמפרטורת קרקע של כ-6°C לפחות בעונה (החוקר ק. קרנר). בקולורדו (כ-40°N) הקו עומד על כ-3,500 מ׳; בסקנדינביה, בקו רוחב 65°N, על כ-650 מ׳; בהימלאיה (כ-28°N) על כ-4,000 מ׳ ויותר. הרוח, עומק השלג ואדמה רדודה הם גורמים משניים שיוצרים צורת ״קרומהולץ״: עצים נמוכים וכפופים.</p>")}
''',toc="רוקי מאונטן: גאולוגיה וקרחונים"))
